INSERT INTO `audit_logs` VALUES (8,'541ae9f2','nl2sql','user','','SELECT service_name, count() AS calls, countIf(is_error = 1) AS errors FROM observability.trace_spans WHERE start_time >= now() - INTERVAL 24 HOUR GROUP BY service_name ORDER BY calls DESC LIMIT 100','ok','{\"rows\": 15}','2026-08-11 01:00:37'),(9,'aeeea5112bb1','approve','1','','','approved','{\"source\": \"ai_chat\"}','2026-08-11 02:46:47'),(10,'e2de7a66ce0e','approve','1','','','approved','{\"source\": \"ai_chat\"}','2026-08-11 03:26:32'),(11,'5e57d7b47b6c','approve','1','','','approved','{\"source\": \"ai_chat\"}','2026-08-11 05:06:37'),(12,'你好','execute','auto','','#!/bin/###############################################################################\n# 诊断脚本 - 定位 OOMKilled / 频繁重启 / Deployment 不可用\n# 用法:\n#   ./diagnose.sh            # 只收集信息，输出诊断结果与修复建议\n#   ./diagnose.sh --fix      # 自动应用安全的修复（需手动确认）\n###############################################################################\n\nset -uo pipefail\n\nDIAG_DIR=\"/tmp/aiops_diagnostics\"\nmkdir -p \"$DIAG_DIR\"\nTS=$(date +%Y%m%d_%H%M%S)\n\necho \"=== 诊断开始: $TS ===\"\necho \"输出目录: $DIAG_DIR\"\n\n# ----------------------------------------------------------------------------\n# 1. 收集所有 Pod 的 OOMKilled 状态\n# ----------------------------------------------------------------------------\necho \"\"\necho \"--- [1] OOMKilled Pod 列表 ---\"\nkubectl get pods -A -o json 2>/dev/null | jq -r \'\n  .items[] as $pod |\n  $pod.status.containerStatuses[]? as $cs |\n  select($cs.lastState.terminated.reason == \"OOMKilled\") |\n  [\n    $pod.metadata.namespace,\n    $pod.metadata.name,\n    $cs.name,\n    $cs.restartCount,\n    $cs.lastState.terminated.startedAt,\n    $cs.lastState.terminated.finishedAt\n  ] | @tsv\' 2>/dev/null | tee \"$DI_DIR/oomkilled_pods.tsv\" || \\\n  kubectl get pods -A -o custom-columns=\'NS:.metadata.namespace,POD:.metadata.name,CONTAINER:.status.containerStatuses[*].name,RESTARTS:.status.containerStatuses[*].restartCount,REASON:.status.containerStatuses[*].lastState.terminated.reason\' | grep OOMKilled || \\\n  echo \"未发现 OOMKilled Pod\"\n\n# ----------------------------------------------------------------------------\n# 2. 重启次数多的 Pod（Top 20）\n# ----------------------------------------------------------------------------\necho \"\"\necho \"--- [2] 重启次数最多的 Pod (Top 20) ---\"\nkubectl get pods -A -o custom-columns=\'NS:.metadata.namespace,POD:.metadata.name,RESTARTS:.status.containerStatuses[*].restartCount,REASON:.status.containerStatuses[*].lastState.terminated.reason\' \\\n  | awk \'NR==1 || $3+0>0\' \\\n  | sort -k3 -nr | head -20 | tee \"$DI_DIR/restart_pods.tsv\"\n\n# -----------------------------------------------------------------','success','{\"output_preview\": \"执行失败: [Errno 2] No such file or directory: \'#!/bin/###############################################################################\'\"}','2026-08-11 13:35:13'),(13,'你好','execute','auto','','#!/usr/bin/env # -*- coding: utf-8 -*-\n# 功能：针对“Pod频繁重启 + Deployment不可用 + OOMKilled”问题的一键诊断与修复辅助脚本\n# 使用方法：在 K8s 集群 master/控制面节点或具有 kubectl 权限的机器上执行 bash script.# 注意：脚本包含只读诊断命令和可选的修复命令（默认不执行，仅打印提示），需要人工确认后手动执行\n\nset -euo pipefail\n\n# 颜色输出\nRED=\'\\033[0;31m\'\nYELLOW=\'\\033[1;33m\'\nGREEN=\'\\033[0;32m\'\nNC=\'\\033[0m\'\n\necho -e \"${GREEN}========== 开始诊断：OOM / 重启 / Deployment 不可用 ==========${NC}\"\n\n# 1. 获取当前所有命名空间中异常 Pod（OOMKilled / 重启次数高 / CrashLoopBackOff）\necho -e \"\\n${YELLOW}[1] 查找 OOMKilled 和异常重启的 Pod${NC}\"\nkubectl get pods -A -o wide | awk \'NR==1 || $3==\"CrashLoopBackOff\" || $3==\"OOMKilled\" || $3==\"Error\" || $3==\"ImagePullBackOff\" || $3==\"RunContainerError\" {print}\'\n\necho -e \"\\n${YELLOW}[2] 按命名空间统计 Pod 重启次数（降序）${NC}\"\nkubectl get pods -A -o json | jq -r \'\n  .items[] | \n  select(.status.containerStatuses != null) |\n  . as $pod |\n  .status.containerStatuses[] |\n  select(.restartCount > 0) |\n  [$pod.metadata.namespace, $pod.metadata.name, .name, .restartCount, (.lastState.terminated.reason // \"N/A\")] |\n  @tsv\' | sort -k4 -nr | head -30\n\necho -e \"\\n${YELLOW}[3] 获取最近 OOMKilled 事件（近1小时）${NC}\"\nkubectl get events -A --field-selector reason=OOMKilling --sort-by=.lastTimestamp | tail -20 || echo \"无 OOMKilling 事件\"\n\necho -e \"\\n${YELLOW}[4] 获取节点资源容量与当前压力${NC}\"\nkubectl top nodes 2>/dev/null || echo \"Metrics Server 不可用，尝试从 node status 获取 allocatable\"\nkubectl describe nodes | grep -E \"Name:|cpu:|memory:|Allocatable:|Requests:|Limits:\" | head -40\n\n# 2. 分析 Deployment 不可用状态\necho -e \"\\n${YELLOW}[5] 检查所有 Deployment 的副本可用性${NC}\"\nkubectl get deployments -A -o custom-columns=\'NAMESPACE:.metadata.namespace,NAME:.metadata.name,DESIRED:.spec.replicas,AVAILABLE:.status.availableReplicas,UNAVAILABLE:.status.unavailableReplicas,READY:.status.readyReplicas\' | awk \'NR==1 || $4!=$3 || $5>0 {print}\'\n\necho -e \"\\n${YELLOW}[6] 获取所有 StatefulSet 的副本可用性${NC}\"\nkubectl get statefulsets -A -o custom-columns=\'NAMESPACE:.metadata.namespace,NAME:.metadata.name,DESIRED:.spec.replicas,AVAILABLE:.status.availableR','success','{\"output_preview\": \"命令解析失败: No closing quotation\"}','2026-08-11 13:36:29'),(14,'你好','execute','auto','','#!/bin/# 基于诊断结果的执行计划：定位 OOM、调整资源、检查 Deployment、观察趋势\nset -uo pipefail\n\necho \"===== 步骤1: 确认 OOMKilled 的具体 Pod 名称 =====\"\nkubectl get pods -A -o json | jq -r \'\n  .items[] as $pod |\n  $pod.status.containerStatuses[]? |\n  select(.lastState.terminated.reason == \"OOMKilled\") |\n  \"\\($pod.metadata.namespace)/\\($pod.metadata.name): container=\\(.name), restartCount=\\(.restartCount), memoryLimit=\\(.resources.limits.memory // \"未设置\")\"\n\' 2>/dev/null || echo \"未找到 OOMKilled 的 Pod 或 jq 不可用\"\n\necho \"\"\necho \"===== 步骤2: 查看事件中的 OOM 记录 =====\"\nkubectl get events -A --sort-by=.lastTimestamp | grep -i oom | tail -30 || true\n\necho \"\"\necho \"===== 步骤3: 查看所有 Pod 的内存 requests/limits =====\"\nkubectl get pod -A -o json | jq -r \'\n  .items[] | .metadata.namespace as $ns | .metadata.name as $pod |\n  .spec.containers[] | [$ns, $pod, .name, .resources.requests.memory // \"-\", .resources.limits.memory // \"-\"] | @tsv\n\' 2>/dev/null | column -t || kubectl get pod -A -o custom-columns=\'NAMESPACE:.metadata.namespace,NAME:.metadata.name,REQUESTS:.spec.containers[*].resources.requests.memory,LIMITS:.spec.containers[*].resources.limits.memory\'\n\necho \"\"\necho \"===== 步骤4: 检查节点内存压力和状态 =====\"\nkubectl top node || true\nkubectl describe node | grep -A 8 \"^Conditions:\" || true\n\necho \"\"\necho \"===== 步骤5: 检查 Deployment 可用性 =====\"\nkubectl get deployment -A -o custom-columns=\'NAMESPACE:.metadata.namespace,NAME:.metadata.name,DESIRED:.spec.replicas,AVAILABLE:.status.availableReplicas,UNAVAILABLE:.status.unavailableReplicas\'\necho \"--- 不可用 Deployment 列表 ---\"\nkubectl get deployment -A | awk \'NR==1 || ($2+0) != ($4+0) {print}\'\n\necho \"\"\necho \"===== 步骤6: 调整内存资源配置（示例，需按实际修改） =====\"\necho \"# 调整个别 Deployment 的 limits（例：将 memcached 的 limit 从 512Mi 提升到 1Gi）\"\necho \"# kubectl -n <namespace> set resources deployment <deployment> --limits=\'memory=1Gi\' --requests=\'memory=512Mi\'\"\necho \"# 或使用 patch: kubectl -n <namespace> patch deployment <deployment> -p \'{\\\"spec\\\":{\\\"template\\\":{\\\"spec\\\":{\\\"containers\\\":[{\\\"name\\\":\\\"<container>\\\",\\\"res','success','{\"output_preview\": \"命令解析失败: No closing quotation\"}','2026-08-11 13:38:08'),(15,'95b083d78fa8','approve','1','','','approved','{\"source\": \"ai_chat\"}','2026-08-12 01:12:44'),(16,'review t','execute','approved','query-api','kubectl get pods -n observability','success','{\"output_preview\": \"$ kubectl get pods -n observability\\n\"}','2026-08-12 02:52:54'),(17,'test-approve','approve','1','query-api','kubectl get pods -n observability','approved','{\"source\": \"ai_chat\"}','2026-08-12 02:52:54'),(18,'9b243b83','approve','1','','kubectl get pods -A -o custom-columns=NAME:.metadata.name,RESTARTS:.status.containerStatuses[*].restartCount,STATUS:.status.phase | sort -k2 -n\nkubectl get events -A --field-selector reason=